import {halfTasks,validHalfEquation} from './half-equations.js?v=20261023-physicscomplete01';
import {showIndustry} from './industry-scenes.js?v=20261023-physicscomplete01';
export const aluminiumTasks=[
{id:'route',title:'Choose the extraction route',prompt:'The starting material is aluminium oxide. Aluminium is above carbon in reactivity.',fields:[['method','Route',[['carbon','Carbon reduction'],['electro','Electrolysis'],['filter','Filtration']],'electro'],['reason','Reason',[['above','Aluminium is above carbon'],['native','Aluminium is already native metal'],['none','The compound has no ions']],'above']],result:'route',why:'Carbon cannot reduce aluminium oxide. Electrolysis decomposes the molten electrolyte.'},
{id:'mixture',title:'Reduce heating demand',prompt:'Keep the cell molten while reducing the temperature required compared with pure aluminium oxide.',fields:[['mixture','Electrolyte',[['water','A cold aqueous solution'],['pure','Only solid aluminium oxide'],['cryolite','Aluminium oxide in molten cryolite']],'cryolite'],['energy','Energy consequence',[['none','No current is needed'],['lower','Less energy needed for heating'],['reverse','The anode becomes negative']],'lower']],result:'mixture',why:'The molten mixture works at a lower temperature. Current and substantial energy are still needed.'},
{id:'anode',title:'Explain the maintenance',prompt:'The hot carbon anodes get shorter while electrolysis continues.',fields:[['cause','Cause',[['react','Oxygen reacts with carbon'],['melt','Aluminium ions turn into carbon'],['cold','Cryolite makes carbon freeze']],'react'],['action','Response',[['stop','Remove the power supply permanently'],['water','Add water to the hot cell'],['replace','Replace the consumed anodes']],'replace']],result:'consumed',why:'Oxygen consumes hot carbon to form carbon dioxide. The anodes must be replaced.'}
];
export function mountIndustryWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const half=l.widget==='industry-half',tasks=half?halfTasks:aluminiumTasks,i=w.task%tasks.length,t=tasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s);
 root.innerHTML=`<p><b>${i+1} / ${tasks.length} · ${t.title}</b></p><p>${t.prompt}</p>`+(half?'<label class="field-label" for="halfEquation">Your half-equation</label><input class="lab-input" id="halfEquation" autocomplete="off" spellcheck="false"><p class="micro-note">Use ->, 3+ and e-. State symbols optional.</p>':t.fields.map(([id,label,opts])=>`<label class="field-label" for="industry-${id}">${label}</label><select class="lab-select" id="industry-${id}"><option value="">Choose…</option>${opts.map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select>`).join(''))+`<button class="secondary" id="checkIndustry">Check ${half?'equation':'decision'}</button><button class="secondary" id="nextIndustry">Next ${half?'equation':'decision'} →</button><p id="industryProgress">${w.passed.length} / ${tasks.length} correct</p>`;
 const draw=()=>showIndustry(half?'half':'cell',half?'':w.passed.includes(t.id)&&t.fields.every(([id,,,answer])=>a[id]===answer)?t.result:'',a.equation||'');if(half){$('#halfEquation').value=a.equation||'';$('#halfEquation').oninput=e=>{a.equation=e.target.value;save();draw();};}else t.fields.forEach(([id])=>{$('#industry-'+id).value=a[id]||'';$('#industry-'+id).onchange=e=>{a[id]=e.target.value;save();showIndustry('cell');};});draw();
 $('#checkIndustry').onclick=()=>{const ok=half?validHalfEquation(a.equation,t.answer):t.fields.every(([id,, ,answer])=>a[id]===answer);if(!ok){feedback(half?'Check element symbols, product formulae, atom totals and total charge. Cathode reactions gain electrons; anode reactions lose them. Use coefficients to balance.':t.why,true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#industryProgress').textContent=`${w.passed.length} / ${tasks.length} correct`;feedback(half?'Correct: species, atom counts and charge balance for this electrode reaction.':t.why);if(w.passed.length===tasks.length){p.widgetDone=true;save();done();}};
 $('#nextIndustry').onclick=()=>{w.task=(i+1)%tasks.length;save();feedback('');mountIndustryWidget(l,p,root,{save,done,feedback});};}
